mapper.select:
SELECT r.id AS return_id, r.return_no, r.order_id, so.order_no, r.source_type, r.customer_id,
    r.customer_name_snapshot AS customer_name, r.status, r.reason, r.decision_reason, r.approved_amount,
    r.approved_at, r.rejected_at, r.cancelled_at, r.version, r.deleted, r.created_at, r.updated_at,
    r.created_by, r.updated_by
FROM xsy_order_return r
LEFT JOIN xsy_sales_order so ON so.id = r.order_id
    AND so.deleted = FALSE
LEFT JOIN xsy_customer c ON c.id = r.customer_id
    AND c.deleted = FALSE
WHERE r.deleted = FALSE



        AND COALESCE(so.seller_id, c.seller_id) IN
        #{scopeId}

    AND FALSE

AND r.customer_id = #{query.customerId}
AND r.status = #{query.status}
AND r.source_type = #{query.sourceType}
AND r.order_id = #{query.orderId}

    AND (r.return_no ILIKE '%' || #{query.keyword} || '%' OR so.order_no ILIKE '%' || #{query.keyword} || '%' OR
        r.customer_name_snapshot ILIKE '%' || #{query.keyword} || '%')

AND r.created_at >= #{query.startTime}
AND r.created_at < #{query.endTime}
ORDER BY r.created_at DESC, r.id DESC

SELECT *
FROM xsy_order_return
WHERE customer_id = #{customerId}
    AND deleted = FALSE
AND order_id = #{orderId}
ORDER BY id DESC
